using System.Collections.Generic;
using UnityEngine;

namespace NeonRushLA.Art
{
    /// <summary>The city's texture catalogue (generated by the Editor builder, previewable offline).</summary>
    public static class CityTextures
    {
        /// <summary>Typical Los Angeles stucco colours: cream, salmon, pale yellow, white, sage, adobe.</summary>
        public static readonly Color[] StuccoTints =
        {
            new Color(0.90f, 0.84f, 0.72f), new Color(0.88f, 0.66f, 0.56f), new Color(0.93f, 0.86f, 0.60f),
            new Color(0.95f, 0.94f, 0.91f), new Color(0.72f, 0.76f, 0.66f), new Color(0.82f, 0.62f, 0.45f),
        };

        public static List<TexSet> All()
        {
            var list = new List<TexSet>
            {
                TextureSynth.Asphalt(),
                TextureSynth.Sidewalk(),
                TextureSynth.Concrete(),
                TextureSynth.Grass(),
                TextureSynth.Plaza(),
                TextureSynth.RoofFlat(),
                TextureSynth.RoofTile(),
                TextureSynth.PalmBark(),
                TextureSynth.Facade(TextureSynth.FacadeKind.Glass, Color.white, "FacadeGlass"),
                TextureSynth.Facade(TextureSynth.FacadeKind.Office, Color.white, "FacadeOffice"),
                TextureSynth.Facade(TextureSynth.FacadeKind.Brick, Color.white, "FacadeBrick"),
                TextureSynth.Facade(TextureSynth.FacadeKind.Storefront, new Color(0f, 0f, 0f), "Storefront0"),
                TextureSynth.Facade(TextureSynth.FacadeKind.Storefront, new Color(0.1f, 0f, 0f), "Storefront1"),
                TextureSynth.Facade(TextureSynth.FacadeKind.Storefront, new Color(0.2f, 0f, 0f), "Storefront2"),
                TextureSynth.ShopSigns(),
            };
            for (int i = 0; i < StuccoTints.Length; i++)
            {
                list.Add(TextureSynth.Facade(TextureSynth.FacadeKind.Stucco, StuccoTints[i], "FacadeStucco" + i));
            }

            return list;
        }
    }
}
